using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Globalization;
namespace DashCanvas {
public static class AssetNames {
 public static readonly string[] BrowserOrder={"GJ_createBtn_001.png","GJ_savedBtn_001.png","GJ_highscoreBtn_001.png","GJ_challengeBtn_001.png","GJ_dailyBtn_001.png","GJ_weeklyBtn_001.png","GJ_eventBtn_001.png","GJ_gauntletsBtn_001.png","GJ_featuredBtn_001.png","GJ_listsBtn_001.png","GJ_pathsBtn_001.png","GJ_mapPacksBtn_001.png","GJ_searchBtn_001.png","GJ_mapBtn_001.png","GJ_versusBtn_001.png"};
 static readonly Dictionary<string,string> Titles=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){
 {"GJ_createBtn_001.png","Create Levels"},{"GJ_savedBtn_001.png","Saved Levels"},{"GJ_highscoreBtn_001.png","Leaderboards"},{"GJ_challengeBtn_001.png","Quests"},{"GJ_dailyBtn_001.png","Daily Level"},{"GJ_weeklyBtn_001.png","Weekly Demon"},{"GJ_eventBtn_001.png","Event Level"},{"GJ_gauntletsBtn_001.png","Gauntlets"},{"GJ_featuredBtn_001.png","Featured Levels"},{"GJ_listsBtn_001.png","Level Lists"},{"GJ_pathsBtn_001.png","Paths"},{"GJ_mapPacksBtn_001.png","Map Packs"},{"GJ_searchBtn_001.png","Search Levels"},{"GJ_mapBtn_001.png","Adventure Map"},{"GJ_versusBtn_001.png","Versus"},
 {"GJ_playBtn_001.png","Play / Start"},{"GJ_profileButton_001.png","Profile / Account"},{"GJ_logo_001.png","Geometry Dash Logo"},{"GJ_garageBtn_001.png","Icon Kit"},{"GJ_creatorBtn_001.png","Open Level Browser"},{"GJ_optionsBtn_001.png","Settings"},{"GJ_achBtn_001.png","Achievements"},{"GJ_statsBtn_001.png","Player Stats"},{"GJ_moreGamesBtn_001.png","More Games"},{"GJ_dailyRewardBtn_001.png","Daily Rewards"},{"GJ_freeChestBtn_001.png","Free Chest"},{"GJ_musicLibraryBtn_001.png","Music Library"},
 {"gj_folderBtn_001.png","Level Folder Button"},{"folderIcon_001.png","Folder Icon"},{"GJ_viewLevelsBtn_001.png","View Levels"},{"GJ_viewListsBtn_001.png","View Level Lists"},{"GJ_listAddBtn_001.png","Add to List"},{"GJ_myListsTxt_001.png","My Lists Heading"},{"topListsLabel_001.png","Top Lists Heading"},{"accountBtn_myLevels_001.png","My Levels"},{"accountBtn_myLists_001.png","My Level Lists"},
 {"GJ_starsIcon_001.png","Level Star Icon"},{"GJ_sStarsIcon_001.png","Small Star Icon"},{"GJ_starsIcon_gray_001.png","Unrated Star Icon"},{"GJ_bigStar_001.png","Large Star"},{"GJ_bigStar_noShadow_001.png","Large Star - No Shadow"},{"GJ_bigStar_glow_001.png","Large Star Glow"},{"star_small01_001.png","Tiny Star"},{"GJ_starBtn_001.png","Rate Stars Button"},{"GJ_starBtn2_001.png","Rate Stars - Alternate"},{"GJ_starBtnMod_001.png","Moderator Star Rating"},
 {"GJ_rateDiffBtn_001.png","Rate Difficulty"},{"GJ_levelLeaderboardBtn_001.png","Level Leaderboard"},{"GJ_downloadBtn_001.png","Download Level"},{"GJ_likeBtn_001.png","Like Level"},{"GJ_newBtn_001.png","New Level"},{"accountBtn_messages_001.png","Messages"},{"accountBtn_friends_001.png","Friends"},{"accountBtn_settings_001.png","Account Settings"}
 };
 public static bool IsBrowser(string n){return BrowserOrder.Contains(n);}
 public static string Section(string name,string group,string fallback){string s=name.ToLowerInvariant();if(IsBrowser(name))return "Level Browser";if(s.Contains("folder")||s.Contains("list")||s.Contains("mylevels"))return "Folders & Lists";if(s.Contains("star")&&!s.Contains("start")||s.Contains("rate")||s.Contains("featured"))return "Stars & Ratings";if(s.StartsWith("edit_"))return "Level Editor";return fallback;}
 public static string Aliases(string n){switch(n){case "GJ_savedBtn_001.png":return "downloaded played visited favorites bookmarks saved folder maps";case "GJ_listsBtn_001.png":return "demon list demonlist level collections maps lists";case "GJ_createBtn_001.png":return "create creator my levels editor build maps";case "GJ_featuredBtn_001.png":return "featured new rated levels maps star";default:return n.ToLowerInvariant().Contains("star")?"star rating rated new maps":"";}}
 public static string Display(string n,string kind,string group){string title;if(Titles.TryGetValue(n,out title))return title;
  if(kind=="glyph"){int code=int.Parse(n.Substring(5));string ch=code>=32&&code<=0x10ffff?char.ConvertFromUtf32(code):"U+"+code.ToString("X4");return Clean(Path.GetFileNameWithoutExtension(group))+" / "+ch;}
  var d=Regex.Match(n,@"^(difficulty|diffIcon)_(\d+|auto)");if(d.Success){var labels=new Dictionary<string,string>{{"00","Unrated"},{"01","Easy"},{"02","Normal"},{"03","Hard"},{"04","Harder"},{"05","Insane"},{"06","Hard Demon"},{"07","Easy Demon"},{"08","Medium Demon"},{"09","Insane Demon"},{"10","Extreme Demon"},{"auto","Auto"}};if(labels.TryGetValue(d.Groups[2].Value,out title))return title+(d.Groups[1].Value=="diffIcon"?" - Small Icon":n.Contains("btn2")?" - Alternate":" - Face");}
  var bg=Regex.Match(n,@"^game_bg_(\d+)");if(bg.Success)return "Background "+bg.Groups[1].Value;
  var p=Regex.Match(n,@"^(player|ship|bird|ball|dart|robot|spider|swing|jetpack)_(\d+)(.*)\.png$");if(p.Success){var types=new Dictionary<string,string>{{"player","Cube"},{"ship","Ship"},{"bird","UFO"},{"ball","Ball"},{"dart","Wave"},{"robot","Robot"},{"spider","Spider"},{"swing","Swing"},{"jetpack","Jetpack"}};string suffix=p.Groups[3].Value;return types[p.Groups[1].Value]+" "+p.Groups[2].Value+(kind=="image"?" - Full Sheet":suffix.Contains("glow")?" - Glow":suffix.StartsWith("_2_")?" - Secondary":suffix.StartsWith("_3_")?" - Detail":" - Base");}
  return Clean(Path.GetFileNameWithoutExtension(n));
 }
 public static string Clean(string s){s=Regex.Replace(s,@"^(GJ_|gj_|edit_|accountBtn_)","");s=Regex.Replace(s,@"_001$","");s=Regex.Replace(s,@"([a-z])([A-Z])","$1 $2");s=s.Replace("_"," ");s=Regex.Replace(s,@"\bBtn\b","Button");s=Regex.Replace(s,@"\bTxt\b","Text");return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(s.Trim());}
}
}
